import * as T from 'three';
export class SoftwareRenderer{
constructor(){this.domElement=document.createElement('canvas');this.ctx=this.domElement.getContext('2d');this.shadowMap={};this.capabilities={getMaxAnisotropy:()=>1};this.ratio=1;this.pc=new T.Vector3();this.world=new T.Vector3();this.normal=new T.Vector3();this.project=new T.Matrix4();this.tris=[];this.cache=new WeakMap()}
setPixelRatio(v){this.ratio=Math.min(v,.8)}setSize(w,h){this.domElement.width=w*this.ratio;this.domElement.height=h*this.ratio;this.w=this.domElement.width;this.h=this.domElement.height;this.domElement.style.width=w+'px';this.domElement.style.height=h+'px'}
render(scene,camera){let c=this.ctx,w=this.w,h=this.h;scene.updateMatrixWorld(true);camera.updateMatrixWorld(true);this.project.multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse);c.fillStyle='#727e96';c.fillRect(0,0,w,h);let grad=c.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#73809e');grad.addColorStop(1,'#c7b7a2');c.fillStyle=grad;c.fillRect(0,0,w,h);this.tris=[];
scene.traverse(o=>{if(!o.isMesh||!o.visible)return;let geo=o.geometry,pos=geo.attributes.position,uv=geo.attributes.uv,idx=geo.index;if(!pos)return;if(o.isSkinnedMesh)o.skeleton.update();let verts=new Array(pos.count);for(let i=0;i<pos.count;i++){this.world.fromBufferAttribute(pos,i);if(o.isSkinnedMesh)o.applyBoneTransform(i,this.world);this.world.applyMatrix4(o.matrixWorld);let e=this.project.elements;let iw=1/(e[3]*this.world.x+e[7]*this.world.y+e[11]*this.world.z+e[15]);this.pc.copy(this.world).applyMatrix4(this.project);verts[i]={iw,x:(this.pc.x*.5+.5)*w,y:(-.5*this.pc.y+.5)*h,z:this.pc.z,wx:this.world.x,wy:this.world.y,wz:this.world.z,u:uv?uv.getX(i):0,v:uv?uv.getY(i):0}}
const count=idx?idx.count:pos.count;for(let i=0;i<count;i+=3){let a=verts[idx?idx.getX(i):i],b=verts[idx?idx.getX(i+1):i+1],d=verts[idx?idx.getX(i+2):i+2];if(a.z>1||b.z>1||d.z>1||a.z< -1||b.z< -1||d.z< -1)continue;let area=(b.x-a.x)*(d.y-a.y)-(b.y-a.y)*(d.x-a.x);if(area>=0)continue;if(Math.max(a.x,b.x,d.x)<0||Math.min(a.x,b.x,d.x)>w||Math.max(a.y,b.y,d.y)<0||Math.min(a.y,b.y,d.y)>h)continue;let m=o.material;if(Array.isArray(m)){let g=geo.groups.find(g=>i>=g.start&&i<g.start+g.count);m=m[g?g.materialIndex:0]}if(!m||m.visible===false)continue;let nx=(b.wy-a.wy)*(d.wz-a.wz)-(b.wz-a.wz)*(d.wy-a.wy),ny=(b.wz-a.wz)*(d.wx-a.wx)-(b.wx-a.wx)*(d.wz-a.wz),nz=(b.wx-a.wx)*(d.wy-a.wy)-(b.wy-a.wy)*(d.wx-a.wx);let n=Math.hypot(nx,ny,nz)||1;let light=m.isMeshBasicMaterial?1:.62+.48*Math.max(0,(-.4*nx+.85*ny+.45*nz)/n);let rgb=m.color||new T.Color('white');let color=rgb.clone().convertLinearToSRGB();let css=`rgb(${Math.min(255,color.r*255*light)},${Math.min(255,color.g*255*light)},${Math.min(255,color.b*255*light)})`;let image=m.map?.image;let texture=image&&m.map.repeat.x===1&&m.map.repeat.y===1?image:null;this.tris.push({a,b,d,m,css,texture: image,depth:(a.z+b.z+d.z)/3,light})}});

let frame=c.getImageData(0,0,w,h),pixels=frame.data,depthBuffer=new Float32Array(w*h);depthBuffer.fill(Infinity);
for(let f of this.tris){let {a,b,d,m}=f;let x0=Math.max(0,Math.floor(Math.min(a.x,b.x,d.x))),x1=Math.min(w-1,Math.ceil(Math.max(a.x,b.x,d.x))),y0=Math.max(0,Math.floor(Math.min(a.y,b.y,d.y))),y1=Math.min(h-1,Math.ceil(Math.max(a.y,b.y,d.y)));let den=(b.y-d.y)*(a.x-d.x)+(d.x-b.x)*(a.y-d.y);if(Math.abs(den)<.01)continue;let tex=null;if(f.texture){tex=this.cache.get(f.texture);if(!tex){let tc=document.createElement('canvas');tc.width=f.texture.width;tc.height=f.texture.height;let tx=tc.getContext('2d');tx.drawImage(f.texture,0,0);tex={data:tx.getImageData(0,0,tc.width,tc.height).data,w:tc.width,h:tc.height};this.cache.set(f.texture,tex)}}let color=(m.color||new T.Color('white')).clone().convertLinearToSRGB(),light=f.light;
for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){let l1=((b.y-d.y)*(x-d.x)+(d.x-b.x)*(y-d.y))/den,l2=((d.y-a.y)*(x-d.x)+(a.x-d.x)*(y-d.y))/den,l3=1-l1-l2;if(l1<0||l2<0||l3<0)continue;let z=l1*a.z+l2*b.z+l3*d.z,i=y*w+x;if(z>=depthBuffer[i])continue;let r=color.r*255,g=color.g*255,bl=color.b*255;if(tex){let iw=l1*a.iw+l2*b.iw+l3*d.iw;let u=(l1*a.u*a.iw+l2*b.u*b.iw+l3*d.u*d.iw)/iw,v=(l1*a.v*a.iw+l2*b.v*b.iw+l3*d.v*d.iw)/iw;if(m.map.flipY)v=1-v;u*=m.map.repeat.x;v*=m.map.repeat.y;u=m.map.wrapS===1000?((u%1)+1)%1:Math.max(0,Math.min(.999999,u));v=m.map.wrapT===1000?((v%1)+1)%1:Math.max(0,Math.min(.999999,v));let ti=(Math.min(tex.h-1,Math.floor(v*tex.h))*tex.w+Math.min(tex.w-1,Math.floor(u*tex.w)))*4;if(tex.data[ti+3]<100)continue;r*=tex.data[ti]/255;g*=tex.data[ti+1]/255;bl*=tex.data[ti+2]/255}depthBuffer[i]=z;let pi=i*4;pixels[pi]=Math.min(255,r*light);pixels[pi+1]=Math.min(255,g*light);pixels[pi+2]=Math.min(255,bl*light);pixels[pi+3]=255}}
c.putImageData(frame,0,0);
}
}
